INSERT INTO "public"."sector_trigger_news" ("id", "source_url", "title", "body", "thumbnail_url", "timestamp", "sector", "sub_sectors", "symbols", "tags", "dimensions", "raw", "created_at", "updated_at", "log_id", "news_index", "published_at", "is_selected", "category", "description", "sitename", "score", "decision", "reason") VALUES ('00166799-dc9c-480e-9ecd-e915dd6bcf52', 'https://market.bisnis.com/read/20260920/192/2005561/susu-ultra-ultj-siapkan-rights-issue-untuk-akuisisi-frisian-flag-rp146-triliun', 'PT Ultra Jaya Milk Industry & Trading Company Tbk (ULTJ) plans a rights issue to fund the Rp14.6 trillion acquisition of PT Frisian Flag Indonesia (FFI)', 'PT Ultra Jaya Milk Industry & Trading Company Tbk (ULTJ) announced a rights issue to finance the acquisition of PT Frisian Flag Indonesia (FFI). The plan calls for issuing up to approximately 7.87 billion new shares at an execution price of Rp2,150 per share, amounting to a total transaction value of about Rp14.6 trillion, with the new shares to be used for the acquisition through an inbreng mechanism. Under the strategic cooperation with FrieslandCampina, the Dutch dairy group will become ULTJ’s new controlling shareholder, holding an estimated 28.95%–30.81% of the company, and will incorporate FFI into the ULTJ group. Rights to subscribe will be transferred by ULTJ’s controlling shareholder to the FFI shareholders—FrieslandCampina International Holding B.V., Blue Waves Group Ventures Pte. Ltd., and PT Bahtera Wiraniaga Internusa. The transaction, which will be followed by a mandatory tender offer, remains subject to approval at an extraordinary general meeting scheduled for 27 October 2026 and to regulatory clearance, and the meeting will also seek consent for a final cash dividend from retained earnings and for changes to the board of directors and commissioners.', 'https://images.bisnis.com/thumb/posts/2026/09/20/2005561/130316-rhn-bisnis-17-industri-_3__1721729920.jpg?w=368&h=208', '2026-09-20 01:28:00+00', 'consumer-non-cyclicals', ARRAY['food-beverage'], ARRAY['ULTJ.JK'], ARRAY['Rights Issue','Mergers & Acquisitions','Capital & Funding','Shareholders General Meeting','Executive Changes','Bearish'], '{"future":1,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":2,"management":1,"sustainability":0}', '{"body":"PT Ultra Jaya Milk Industry & Trading Company Tbk (ULTJ) announced a rights issue to finance the acquisition of PT Frisian Flag Indonesia (FFI). The plan calls for issuing up to approximately 7.87 billion new shares at an execution price of Rp2,150 per share, amounting to a total transaction value of about Rp14.6 trillion, with the new shares to be used for the acquisition through an inbreng mechanism. Under the strategic cooperation with FrieslandCampina, the Dutch dairy group will become ULTJ’s new controlling shareholder, holding an estimated 28.95%–30.81% of the company, and will incorporate FFI into the ULTJ group. Rights to subscribe will be transferred by ULTJ’s controlling shareholder to the FFI shareholders—FrieslandCampina International Holding B.V., Blue Waves Group Ventures Pte. Ltd., and PT Bahtera Wiraniaga Internusa. The transaction, which will be followed by a mandatory tender offer, remains subject to approval at an extraordinary general meeting scheduled for 27 October 2026 and to regulatory clearance, and the meeting will also seek consent for a final cash dividend from retained earnings and for changes to the board of directors and commissioners.","tags":["Rights Issue","Mergers & Acquisitions","Capital & Funding","Shareholders General Meeting","Executive Changes","Bearish"],"title":"PT Ultra Jaya Milk Industry & Trading Company Tbk (ULTJ) plans a rights issue to fund the Rp14.6 trillion acquisition of PT Frisian Flag Indonesia (FFI)","sector":"consumer-non-cyclicals","source":"https://market.bisnis.com/read/20260920/192/2005561/susu-ultra-ultj-siapkan-rights-issue-untuk-akuisisi-frisian-flag-rp146-triliun","symbols":["ULTJ.JK"],"dimension":{"future":1,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":2,"management":1,"sustainability":0},"thumbnail":"https://images.bisnis.com/thumb/posts/2026/09/20/2005561/130316-rhn-bisnis-17-industri-_3__1721729920.jpg?w=368&h=208","timestamp":"2026-09-20T01:28:00","sub_sector":["food-beverage"]}', '2026-09-21 01:00:10.881891+00', '2026-09-21 01:00:10.881891+00', '93a52bb7-fda1-4d45-8b20-21812bcfb569', 5, '2026-09-20 01:28:00+00', false, null, null, null, 0, 'PASS', null), ('04afd1f4-31f2-4e6e-9dc5-26c053649db9', 'https://www.idxchannel.com/market-news/tlkm-resmi-kuasai-seluruh-saham-telkom-data-ekosistem', 'TLKM Resmi Kuasai Seluruh Saham Telkom Data Ekosistem', 'Advertisement IDX Channel Market news TLKM Resmi Kuasai Seluruh Saham Telkom Data Ekosistem Market news Dhera Arizona Pratiwi 19/09/2026 06:00 WIB PT Telkom Indonesia (Persero) Tbk (TLKM) melakukan transaksi pembelian seluruh saham PT Sigma Cipta Caraka (Telkomsigma) di PT Telkom Data Ekosistem (TDE). TLKM Resmi Kuasai Seluruh Saham Telkom Data Ekosistem. (Foto Istimewa) A A A IDXChannel - PT Telkom Indonesia (Persero) Tbk (TLKM) melakukan transaksi pembelian seluruh saham PT Sigma Cipta Caraka (Telkomsigma) di PT Telkom Data Ekosistem (TDE). Dilansir dari keterbukaan informasi, Sabtu (19/9/2026), Telkom membeli 1.445.020 Saham Seri A dan 2.015.637.361.776 Saham Seri B atau 19,19 persen dari seluruh saham TDE yang telah dikeluarkan dan disetor penuh milik Telkomsigma. Baca Juga: Pendapatan Naik 3,9 Persen di Juni, Intip Strategi TLKM Pacu Kinerja hingga Akhir 2026 "Ini dilakukan dalam rangka mendukung Unlock DC Co Telkom melalui Strategic Partnership serta program streamlining Telkom Group," ujar SVP Corporate Secretary TLKM Edie Kurniawan. Sehubungan dengan pembelian tersebut, kata Edie, 10.504.517.594.408 saham atau 100 persen saham TDE menjadi milik Telkom. Baca Juga: Telkom (TLKM) Buka Peluang Tambah Dividen dari Hasil Divestasi dan Monetasi Aset Halaman : 1 2 Your browser does not support the audio tag. LISTEN SHARE Follow Saluran Whatsapp IDX Channel untuk Update Berita Ekonomi Follow Follow Berita IDX Channel di Google News TAG: TLKM Telkom Indonesia Telkom Data Ekosistem Tim Editor Dhera Arizona Pratiwi Reporter Dhera Arizona Pratiwi Editor Berita Rekomendasi Pendapatan Naik 3,9 Persen di Juni, Intip Strategi TLKM Pacu Kinerja hingga Akhir 2026 Berita Terkait Telkom (TLKM) Buka Peluang Tambah Dividen dari Hasil Divestasi dan Monetasi Aset 07/09/2026 13:57 WIB Infranexia dan XLSMART (EXCL) Kolaborasi Perkuat Infrastruktur Konektivitas Nasional 07/09/2026 11:58 WIB Potensi Infrastruktur AI Membesar, Dua Emiten Telko Ini Berpotensi Cuan 28/08/2026 06:28 WIB Bisnis Data Center Indonesia Masuk Fase Awal, Deretan Saham Berpeluang Cuan 24/08/2026 10:22 WIB Telkom (TLKM) Optimalkan Satelit Telkomsat di 17 Titik Terdampak Gempa NTT 18/08/2026 13:47 WIB Limpahan Data Center Regional, DCII hingga DSSA Jadi Sorotan 18/08/2026 06:24 WIB Berita Lainnya TLKM Resmi Kuasai Seluruh Saham Telkom Data Ekosistem 19/09/2026 06:00 WIB Ultra Voucher (UVCR) Mau Gelar Rights Issue, Terbitkan 200 Juta Saham Baru 19/09/2026 05:05 WIB Samudera Indonesia (SMDR) Suntik Modal ke Dua Anak Usaha Senilai Rp40,70 Miliar 19/09/2026 04:04 WIB Pencari Rumah Mulai Hitung Waktu Tempuh, Properti di Jakarta Pusat Kian Diminati 19/09/2026 03:03 WIB BPKN Desak Produsen Beras Fortifikasi Palsu Berikan Ganti Rugi kepada Konsumen 19/09/2026 02:02 WIB Lebih 44 Ribu Anak dari Keluarga Miskin Kembali Dapatkan Akses Sekolah Gratis 19/09/2026 01:01 WIB Advertisement Advertisement Populer Berita Utama Haji Isam Resmi Caplok Bayan, Saham BYAN, JARR hingga TEBE Terbang Nasib Saham Summarecon (SMRA) usai Presdir Ditangkap KPK, Masih Menarik? Momentum Saham Hapsoro-Prajogo SINI, Seberapa Jauh Reli Berlanjut? Minat Investasi Emas Meningkat, HSBC Indonesia Hadirkan Reksa Dana Syariah 10 Saham Top Gainer Perdagangan Jumat 18 September 2026, Ada BYAN hingga CAMP TLKM Resmi Kuasai Seluruh Saham Telkom Data Ekosistem Ultra Voucher (UVCR) Mau Gelar Rights Issue, Terbitkan 200 Juta Saham Baru Samudera Indonesia (SMDR) Suntik Modal ke Dua Anak Usaha Senilai Rp40,70 Miliar Wall Street Melemah Akibat Tekanan dari Kenaikan Imbal Hasil Obligasi Treasury Warren Buffett Mundur Sebagai Chairman Berkshire, Digantikan Putranya Howard', 'https://img.idxchannel.com/media/500/images/idx/2026/07/07/telkom_tlkm.jpg', '2026-09-18 23:01:45.682+00', null, null, ARRAY['TLKM'], null, null, null, '2026-09-18 23:01:46.221727+00', '2026-09-18 23:01:47.41+00', null, null, '2026-09-18 23:01:45.682+00', false, 'CORPORATE_ACTION', 'PT Telkom Indonesia (Persero) Tbk (TLKM) melakukan transaksi pembelian seluruh saham PT Sigma Cipta Caraka (Telkomsigma) di PT Telkom Data Ekosistem (TDE).', 'https://www.idxchannel.com/', null, 'PASS', null), ('0ebe961c-5af5-4f6a-a3c8-1bac197cb58d', 'https://emitennews.com/news/diskon-gede-pengendali-jual-puluhan-juta-saham-mglv', 'Nextier Datamate Center sells 38.5 million NexAI Digital (MGLV) shares at a 54.25% discount, cutting its stake to 63.07%', 'Nextier Datamate Center, the controlling shareholder of NexAI Digital (MGLV), sold an additional 38.5 million shares on 11 September 2026 at roughly Rp7,000 per share, generating proceeds of about Rp269.5 billion. The sale price represented a discount of approximately 8,300 points, or 54.25%, compared with the closing price of Rp15,300 on that day. After the transaction, Nextier’s holding in NexAI Digital fell to 1.2 billion shares, or 63.07% of the total, a decline of 2.03 percentage points from the prior 65.10% stake. This follows an earlier sale of 35 million shares on 8 September 2026 at the same price, which raised Rp245 billion, and comes after a special shareholders’ meeting on 7 September 2026 that approved a right issue of up to 285.73 million new shares, the sale of subsidiaries, and the appointment of Widjono Hardjanto as an independent commissioner.', 'https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789527856.jpg?25119ab', '2026-09-16 10:15:00+00', 'consumer-cyclicals', ARRAY['household-goods'], ARRAY['MGLV.JK'], ARRAY['Ownership','Rights Issue','Shareholders General Meeting','Executive Changes','Capital & Funding','Bearish'], '{"future":0,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":0,"management":1,"sustainability":0}', '{"body":"Nextier Datamate Center, the controlling shareholder of NexAI Digital (MGLV), sold an additional 38.5 million shares on 11 September 2026 at roughly Rp7,000 per share, generating proceeds of about Rp269.5 billion. The sale price represented a discount of approximately 8,300 points, or 54.25%, compared with the closing price of Rp15,300 on that day. After the transaction, Nextier’s holding in NexAI Digital fell to 1.2 billion shares, or 63.07% of the total, a decline of 2.03 percentage points from the prior 65.10% stake. This follows an earlier sale of 35 million shares on 8 September 2026 at the same price, which raised Rp245 billion, and comes after a special shareholders’ meeting on 7 September 2026 that approved a right issue of up to 285.73 million new shares, the sale of subsidiaries, and the appointment of Widjono Hardjanto as an independent commissioner.","tags":["Ownership","Rights Issue","Shareholders General Meeting","Executive Changes","Capital & Funding","Bearish"],"title":"Nextier Datamate Center sells 38.5 million NexAI Digital (MGLV) shares at a 54.25% discount, cutting its stake to 63.07%","sector":"consumer-cyclicals","source":"https://emitennews.com/news/diskon-gede-pengendali-jual-puluhan-juta-saham-mglv","symbols":["MGLV.JK"],"dimension":{"future":0,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":0,"management":1,"sustainability":0},"thumbnail":"https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789527856.jpg?25119ab","timestamp":"2026-09-16T10:15:00","sub_sector":["household-goods"]}', '2026-09-17 06:49:25.547472+00', '2026-09-17 06:49:25.547472+00', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 4, '2026-09-16 10:15:00+00', false, null, null, null, 0, 'PASS', null), ('105b5e6e-6b9c-4e25-9b01-fcf45a97f232', 'https://emitennews.com/news/inet-akuisisi-60-saham-sgi-bidik-pendapatan-berulang-jangka-panjang', 'PT Sinergi Inti Andalan Prima Tbk (INET) to acquire 60% of PT Sarana Global Indonesia', 'PT Sinergi Inti Andalan Prima Tbk (INET) announced it will acquire a 60% stake in PT Sarana Global Indonesia. The deal is intended to give INET integrated undersea cable infrastructure capabilities, covering planning, construction, operation and maintenance. SGI contributes extensive EPC experience, a dedicated cable vessel Pacific Guardian, a cable-lay barge Nostag 10, and long-term maintenance contracts that generate recurring revenue. The acquisition positions INET to capture steady income from SGI’s existing contracts on the Palapa Ring and other submarine cable projects.', 'https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789621361.jpeg?25119ab', '2026-09-17 12:04:00+00', 'infrastructures', ARRAY['telecommunication'], ARRAY['INET.JK'], ARRAY['Mergers & Acquisitions','Business Expansion','Bullish'], '{"future":0,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":0,"management":0,"sustainability":0}', '{"body":"PT Sinergi Inti Andalan Prima Tbk (INET) announced it will acquire a 60% stake in PT Sarana Global Indonesia. The deal is intended to give INET integrated undersea cable infrastructure capabilities, covering planning, construction, operation and maintenance. SGI contributes extensive EPC experience, a dedicated cable vessel Pacific Guardian, a cable-lay barge Nostag 10, and long-term maintenance contracts that generate recurring revenue. The acquisition positions INET to capture steady income from SGI’s existing contracts on the Palapa Ring and other submarine cable projects.","tags":["Mergers & Acquisitions","Business Expansion","Bullish"],"title":"PT Sinergi Inti Andalan Prima Tbk (INET) to acquire 60% of PT Sarana Global Indonesia","sector":"infrastructures","source":"https://emitennews.com/news/inet-akuisisi-60-saham-sgi-bidik-pendapatan-berulang-jangka-panjang","symbols":["INET.JK"],"dimension":{"future":0,"dividend":0,"ownership":2,"technical":0,"valuation":0,"financials":0,"management":0,"sustainability":0},"thumbnail":"https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789621361.jpeg?25119ab","timestamp":"2026-09-17T12:04:00","sub_sector":["telecommunication"]}', '2026-09-18 03:17:19.846276+00', '2026-09-18 03:17:19.846276+00', '6b73e037-ad0f-4943-8c10-a1842c6df0c6', 5, '2026-09-17 12:04:00+00', false, null, null, null, 0, 'PASS', null), ('1325cfce-edb3-413f-a989-0e0f1bfc4556', 'https://emitennews.com/news/akuisisi-frisian-flag-rp1456t-ultj-siapkan-right-issue-rp1692t', 'PT Ultrajaya Milk Industry & Trading Company Tbk (ULTJ) to acquire PT Frisian Flag Indonesia (FFI) for Rp14.56 trillion and launch a Rp16.92 trillion right issue', 'PT Ultrajaya Milk Industry & Trading Company Tbk (ULTJ) announced it will acquire 100% of PT Frisian Flag Indonesia (FFI) for Rp14.56 trillion. To fund the transaction, ULTJ plans a right issue of Rp16.92 trillion. The acquisition aims to strengthen ULTJ’s operational and financial capabilities, expand its product portfolio—including UHT milk, non‑dairy drinks, and child nutrition products—and increase production capacity through combined facilities in West Java and Jakarta. The deal, disclosed on 20 September 2026, is expected to support ULTJ’s long‑term business expansion.', 'https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789867395.jpeg?25119ab', '2026-09-20 08:31:00+00', 'consumer-non-cyclicals', ARRAY['food-beverage'], ARRAY['ULTJ.JK'], ARRAY['Mergers & Acquisitions','Rights Issue','Business Expansion','Capital & Funding','Bullish'], '{"future":1,"dividend":0,"ownership":0,"technical":0,"valuation":1,"financials":2,"management":0,"sustainability":0}', '{"body":"PT Ultrajaya Milk Industry & Trading Company Tbk (ULTJ) announced it will acquire 100% of PT Frisian Flag Indonesia (FFI) for Rp14.56 trillion. To fund the transaction, ULTJ plans a right issue of Rp16.92 trillion. The acquisition aims to strengthen ULTJ’s operational and financial capabilities, expand its product portfolio—including UHT milk, non‑dairy drinks, and child nutrition products—and increase production capacity through combined facilities in West Java and Jakarta. The deal, disclosed on 20 September 2026, is expected to support ULTJ’s long‑term business expansion.","tags":["Mergers & Acquisitions","Rights Issue","Business Expansion","Capital & Funding","Bullish"],"title":"PT Ultrajaya Milk Industry & Trading Company Tbk (ULTJ) to acquire PT Frisian Flag Indonesia (FFI) for Rp14.56 trillion and launch a Rp16.92 trillion right issue","sector":"consumer-non-cyclicals","source":"https://emitennews.com/news/akuisisi-frisian-flag-rp1456t-ultj-siapkan-right-issue-rp1692t","symbols":["ULTJ.JK"],"dimension":{"future":1,"dividend":0,"ownership":0,"technical":0,"valuation":1,"financials":2,"management":0,"sustainability":0},"thumbnail":"https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789867395.jpeg?25119ab","timestamp":"2026-09-20T08:31:00","sub_sector":["food-beverage"]}', '2026-09-21 01:00:10.881891+00', '2026-09-21 01:00:10.881891+00', '93a52bb7-fda1-4d45-8b20-21812bcfb569', 4, '2026-09-20 08:31:00+00', false, null, null, null, 0, 'PASS', null), ('137f528d-5414-4880-a612-2d6800d40ef9', 'https://katadata.co.id/finansial/bursa/6ab06a006da37/asa-himbara-gotong-royong-restrukturisasi-utang-adhi-karya-adhi-rp-3-triliun', 'Asa Himbara Gotong Royong Restrukturisasi Utang Adhi Karya (ADHI) Rp 3 Triliun - Bursa Katadata.co.id', 'Asa Himbara Gotong Royong Restrukturisasi Utang Adhi Karya (ADHI) Rp 3 Triliun Oleh Nur Hana Putri Nabila 21 September 2026, 06:19 ANTARA FOTO/ Reno Esnir/hp. Suasana pengerjaan proyek pembangunan Light Rail Transit (LRT) Jabodebek di ruas Jalan Rasuna Said, Jakarta, Sabtu (1/5/2021). Membuat ringkasan dengan AI Tiga bank Himpunan Bank Milik Negara atau Himbara bergotong royong merestrukturisasi utang emiten konstruksi BUMN PT Adhi Karya (Persero) Tbk (ADHI) senilai Rp3 triliun melalui Master Restructuring Agreement (MRA).Restrukturisasi tersebut diteken pada 18 September 2026 dan menggandeng PT Bank Mandiri (Persero) Tbk (BMRI), PT Bank Rakyat Indonesia (Persero) Tbk (BBRI), dan PT Bank Negara Indonesia (Persero) Tbk (BBNI) sebagai kreditur.Direktur Keuangan Adhi Karya, Bani Iqbal mengatakan Adhi Karya bertindak sebagai debitur sekaligus penerima fasilitas. Kepemilikan saham perseroan di antaranya Pemerintah Republik Indonesia sebesar 0,64% melalui saham Seri A Dwiwarna dan PT Danantara Asset Management sebesar 63,70% melalui saham Seri B.“PT Bank Mandiri (Persero) Tbk, selaku Agen Fasilitas turut serta juga menandatangani MRA ini,” tulis Bani Iqbal dalam keterbukaan informasi BEI, dikutip Senin (21/9). Bani mengatakan ketiga bank tersebut juga merupakan BUMN yang sahamnya dimiliki oleh Pemerintah Republik Indonesia dan PT Danantara Asset Management. Ia menyebut Adhi Karya dan ketiga kreditur memiliki hubungan afiliasi karena berada di bawah kendali langsung pemegang saham yang sama, yakni Pemerintah Republik Indonesia dan PT Danantara Asset Management.Baca JugaRUNS Matangkan Rencana IPO Anak Usaha eCampuz, Bersiap Luncurkan Bisnis Model AIIHSG Rawan Terkoreksi, Saham BBCA, TPIA, MDKA dan TLKM Jadi Rekomendasi AnalisWall Street Bergejolak Tersengat Harga Minyak dan Imbal Hasil US Treasury NaikAdapun skema restrukturisasi utang itu dibagi menjadi tiga kelompok pembayaran (tranche). Tranche A menjadi pinjaman term loan sebesar Rp 1,54 triliun yang akan dilunasi selama 15 tahun sejak tanggal efektif menggunakan skema balloon payment. Dengan tingkat bunga 3,5% per tahun dan 1% dibayar tunai tiap 3 bulan dan 2,5% ditangguhkan hingga 2041. Tranche B mencakup pinjaman term loan senilai Rp 1,45 triliun yang akan diselesaikan dalam kurun 5 tahun sejak Tanggal Efektif melalui skema bullet payment dari hasil divestasi Perseroan, dan dikenakan bunga 1% per tahun yang dibayar tiap 3 bulan. Sementara itu, Tranche C mencakup kewajiban bunga/bagi hasil sejak Tanggal Persetujuan Standstill hingga Tanggal Efektif akan dicicil selama 18 bulan sejak Tanggal Efektif tanpa dikenakan bunga atau bagi hasil tambahan.Bani mengatakan restrukturisasi itu demi menata kembali utang ADHI sekaligus mendorong transformasi bisnis dan keuangan perseroan. Langkah tersebut bertujuan menjaga keberlangsungan usaha, memperbaiki kinerja operasional dan keuangan, dan meningkatkan kemampuan perseroan dalam melunasi seluruh kewajibannya kepada kreditur.Fokus Bisnis Inti Engineering dan KonstruksiDirektur Utama ADHI Moeharmein Zein Chaniago mengatakan penandatanganan MRA menjadi awal tahap implementasi yang membutuhkan komitmen dan konsistensi seluruh pihak.“Kami optimis dengan sinergi erat antara ADHI, DIM, dan perbankan sebagai kreditur, kami dapat membangun fundamental bisnis yang lebih sehat, menciptakan pertumbuhan berkelanjutan, serta meningkatkan kontribusi terhadap pembangunan dan perekonomian RI,” ujar Moeharmein.ADHI berkomitmen menjalankan MRA secara transparan dan akuntabel dan menjaga komunikasi dengan seluruh pemangku kepentingan.Sejalan dengan restrukturisasi, ADHI melanjutkan transformasi perusahaan dengan memfokuskan bisnis pada sektor inti engineering dan konstruksi. Perseroan juga melakukan streamlining organisasi dan portofolio bisnis, meningkatkan operational excellence berbasis teknologi, dan memperkuat pengelolaan keuangan dan procurement.ADHI memastikan kegiatan operasional dan pengerjaan proyek tetap berjalan normal untuk menjaga keberlangsungan usaha dan menyelesaikan proyek yang menjadi tanggung jawab perseroan. Ia menyebut keberlanjutan bisnis konstruksi ADHI juga dinilai berdampak terhadap masyarakat melalui penciptaan lapangan kerja, perputaran ekonomi di sekitar proyek, dan keberlanjutan pembangunan infrastruktur. Berita Katadata.co.id di WhatsApp Anda Dapatkan akses cepat ke berita terkini dan data berharga dari WhatsApp Channel Katadata.co.id Ikuti kami Baca artikel ini lewat aplikasi mobile. Dapatkan pengalaman membaca lebih nyaman dan nikmati fitur menarik lainnya lewat aplikasi mobile Katadata. Reporter: Nur Hana Putri Nabila Editor: Ira Guslina Sufa #Adhi Karya#Update MeCek juga data ini', 'https://cdn1.katadata.co.id/media/images/thumb/2021/05/01/2021_05_01-18_40_00_b1b3f6cb3e8fd2bb96e60de8eefb550b_960x640_thumb.jpg', '2026-09-20 23:21:33.111+00', null, null, ARRAY['ADHI.JK'], null, null, null, '2026-09-20 23:21:33.647765+00', '2026-09-20 23:21:33.647765+00', null, null, '2026-09-20 23:21:33.111+00', false, 'CORPORATE_ACTION', 'Tiga bank Himpunan Bank Milik Negara atau Himbara bergotong royong merestrukturisasi utang emiten konstruksi BUMN PT Adhi Karya (Persero) Tbk (ADHI) senilai Rp3 triliun melalui MRA', 'Katadata', 9, 'GENERATE', 'Berita memiliki catalyst jelas (restrukturisasi utang/MRA) dengan data kuantitatif yang sangat detail (nilai Rp3 triliun, skema tranche A/B/C, bunga, dan tenor) serta ticker yang spesifik.'), ('154bba37-2bb0-4bc7-8b50-dc26fbe4c60d', 'https://www.idxchannel.com/market-news/sofa-siapkan-pendanaan-rp131-miliar-untuk-proyek-wte-hingga-2028', 'SOFA Siapkan Pendanaan Rp131 Miliar untuk Proyek WTE hingga 2028', 'Advertisement IDX Channel Market news SOFA Siapkan Pendanaan Rp131 Miliar untuk Proyek WTE hingga 2028 Market news Desi Angriani 19/09/2026 11:35 WIB Sumber pendanaan yang disiapkan antara lain berasal dari hasil pelaksanaan rights issue, pinjaman bank, maupun kombinasi keduanya. SOFA Siapkan Pendanaan Rp131 Miliar untuk Proyek WTE hingga 2028 (Foto: dok Freepik) A A A IDXChannel – PT Solusi Environment Asia Tbk (SOFA) memperkirakan kebutuhan pendanaan untuk proyek waste-to-energy (WTE) selama periode konstruksi hingga kuartal II 2028 mencapai Rp131 miliar. SOFA melalui anak usahanya, PT Ananta Energi Asia (AEA), telah melakukan penyertaan modal kepada PT Weiming Nusantara Alpha (WNA) dan PT Weiming Nusantara Gamma (WNG) sebesar USD200.000 atau sekitar Rp3,36 miliar. Baca Juga: Beralih ke Bisnis EBT, SOFA Gelar Rights Issue 50 Miliar Saham "Nilai penyertaan modal tersebut dilakukan sesuai dengan porsi kepemilikan AEA pada masing-masing entitas," tulis manajemen SOFA dalam surat kepada Bursa, Jumat (18/9/2026) Selanjutnya, WNA dan WNG akan melakukan peningkatan modal secara bertahap mengikuti kebutuhan pendanaan proyek selama masa konstruksi. Baca Juga: Anak Usaha SOFA Jadi Mitra Zhejian Weiming Kelola PSEL di Bali dan Bogor Adapun besaran penyertaan modal SOFA melalui AEA akan disesuaikan dengan kebutuhan pendanaan proyek serta porsi kepemilikan AEA pada WNA dan WNG. Halaman : 1 2 Your browser does not support the audio tag. LISTEN SHARE Follow Saluran Whatsapp IDX Channel untuk Update Berita Ekonomi Follow Follow Berita IDX Channel di Google News TAG: SOFA WTE Solusi Environment Tim Editor Desi Angriani Reporter Desi Angriani Editor Berita Rekomendasi PSEL Bogor Raya Berpotensi Olah 1.500 Ton Sampah per Hari Berita Terkait Danantara Klaim PSEL Bogor Raya Bisa Kurangi Timbulan Sampah hingga 45 Persen 17/09/2026 13:00 WIB Tambah Dua Usaha Baru, SOFA Bidik Holding Pengelolaan Lingkungan dan Energi 29/08/2026 14:03 WIB Percepat Pengembangan Proyek WtE di Indonesia, Begini Strategi Danantara 05/08/2026 18:15 WIB BNBR Klarifikasi Status Bakrie Power di Proyek WtE Surabaya 22/07/2026 10:40 WIB Perkuat Portofolio WtE, OASA Siap Garap Proyek PSEL Lampung Raya 20/07/2026 22:18 WIB Dari Sampah Jadi Listrik (WtE), TPIA dan BNBR Berebut Peluang Bisnis Baru 16/07/2026 10:04 WIB Berita Lainnya SOFA Siapkan Pendanaan Rp131 Miliar untuk Proyek WTE hingga 2028 19/09/2026 11:35 WIB Prabowo Naik Maung Hadiri 100 Tahun Gontor di Jatim 19/09/2026 11:19 WIB BIKE Gandeng Perumda Pasar Jaya Kembangkan Pasar Minggu, Nilai Investasi Rp1 Triliun 19/09/2026 11:05 WIB Daftar 10 Saham yang Merugi Sepekan, SAPX Merosot 39 Persen 19/09/2026 10:38 WIB Induk Frisian Flag Bakal Jadi Pengendali Baru Ultrajaya (ULTJ), Begini Prospeknya 19/09/2026 10:33 WIB Harga Emas di Pegadaian Kompak Naik, Antam 1 Gram Tembus Rp2,66 Juta 19/09/2026 09:44 WIB Advertisement Advertisement Populer Berita Utama Haji Isam Resmi Caplok Bayan, Saham BYAN, JARR hingga TEBE Terbang Rebalancing FTSE, Saham BSDE hingga SCMA Tertekan di Menit Akhir Nasib Saham Summarecon (SMRA) usai Presdir Ditangkap KPK, Masih Menarik? 10 Saham Top Gainer Perdagangan Jumat 18 September 2026, Ada BYAN hingga CAMP Minat Investasi Emas Meningkat, HSBC Indonesia Hadirkan Reksa Dana Syariah SOFA Siapkan Pendanaan Rp131 Miliar untuk Proyek WTE hingga 2028 BIKE Gandeng Perumda Pasar Jaya Kembangkan Pasar Minggu, Nilai Investasi Rp1 Triliun Daftar 10 Saham yang Merugi Sepekan, SAPX Merosot 39 Persen Induk Frisian Flag Bakal Jadi Pengendali Baru Ultrajaya (ULTJ), Begini Prospeknya Harga Emas di Pegadaian Kompak Naik, Antam 1 Gram Tembus Rp2,66 Juta', 'https://img.idxchannel.com/media/500/images/idx/2025/10/18/pengolahan_sampah_freepik.jpg', '2026-09-19 04:37:48.813+00', null, null, ARRAY['SOFA.JK'], null, null, null, '2026-09-19 04:37:49.718416+00', '2026-09-19 04:37:50.887+00', null, null, '2026-09-19 04:37:48.813+00', false, 'CORPORATE_ACTION', 'Sumber pendanaan yang disiapkan antara lain berasal dari hasil pelaksanaan rights issue, pinjaman bank, maupun kombinasi keduanya.', 'https://www.idxchannel.com/', null, 'PASS', null), ('1ba50b3f-baa1-4bad-b843-13cada0b6d2f', 'https://www.cnbcindonesia.com/market/20260921081739-17-769405/ihsg-masih-volatil-deretan-saham-ini-menarik-buat-dilirik', 'IHSG Masih Volatil, Deretan Saham Ini Menarik Buat Dilirik', 'IHSG Masih Volatil, Deretan Saham Ini Menarik Buat Dilirik Comment SHARE url telah tercopy CNBC Indonesia 21 September 2026 08:48 Mega Capital Sekuritas PT Mega Capital Sekuritas, bagian dari CT Corpora, hadir sejak 1991 dengan layanan investasi inovatif dan tenaga ahli terpercaya. Ilustrasi grafik saham dalam latar belakang hitam Jakarta, CNBC Indonesia - Indeks Harga Saham Gabungan (IHSG) mengakhiri perdagangan Jumat (18/9) di zona merah, turun 0,33% ke level 6.441,16. Sejumlah saham mencatat pergerakan positif, di antaranya BYAN yang naik 19,96%, DCII menguat 3,14%, dan BREN naik 3,25%. Di sisi lain, AMMN turun 4,49%, BMRI terkoreksi 2,07%, dan DSSA melemah 5,36%. Investor asing membukukan net sell sebesar Rp1,78 triliun di pasar reguler dan Rp1,79 triliun di seluruh pasar. Secara sektoral, 10 dari 11 sektor berada di zona merah. Sektor Industrials mencatat penurunan 1,64%, sedangkan sektor Technology menjadi satu-satunya sektor yang menguat, naik 0,27%. Pergerakan bursa saham Amerika Serikat (AS) ditutup bervariasi. Dow Jones turun 0,18% ke 51.682, sementara S&P 500 naik 0,17% ke 7.650 dan Nasdaq menguat 0,40% ke 26.522. Rebalancing FTSE turut memengaruhi arus dana di pasar saham Indonesia. Kondisi tersebut mendorong aksi jual bersih yang tercatat pada level tertinggi sejak 19 Juni, termasuk pada sejumlah emiten yang mengalami perubahan klasifikasi ke Micro Cap seperti BSDE, SCMA, dan BBYB. Pergerakan indeks offshore Indonesia juga mengalami koreksi, dengan ETF EIDO turun 2,04% dan MSCI Indonesia melemah 1,24%. Dari sisi aksi korporasi, ada PT Erajaya Swasembada Tbk (ERAA) yang menyiapkan pengembangan bisnis makanan dan minuman (F&B) ke pasar global melalui lini Erajaya Food & Nourishment (EFN). EFN sebelumnya telah membangun portofolio bisnis di pasar domestik melalui sejumlah merek, seperti Paris Baguette, Bacha Coffee, Curry Up, CHAGEE, Wetzel''s Pretzels, hingga GrandLucky Superstore. Selain menambah portofolio merek, EFN juga memperkuat rantai pasok melalui pendekatan direct sourcing GrandLucky. Salah satunya dilakukan melalui pengembangan jaringan pasok dengan merek Brastagi di Medan. Perseroan juga mengembangkan greenhouse dan hydroponic farming serta skema offtake untuk memperluas akses pasar bagi produk yang dihasilkan petani. Ke depan, EFN diarahkan untuk membangun portofolio bisnis yang lebih beragam dalam ekosistem Erajaya Group. Selanjutnya, ada PT Bhineka Inovasi Ketahanan Energi Tbk (BIKE) yang melalui anak usahanya, Ratu Karya, menandatangani nota kesepahaman (MoU) dengan Perumda Pasar Jaya pada 17 September 2026. MoU tersebut berkaitan dengan rencana pembangunan dan pengembangan kawasan Pasar Minggu, Jakarta Selatan, dengan estimasi nilai investasi sekitar Rp1 triliun. Kawasan yang direncanakan akan dikembangkan tersebut mencakup sejumlah fasilitas, mulai dari kios dan los bagi pelaku usaha mikro, kecil, dan menengah (UMKM), rumah susun, rumah sakit, gedung perkantoran, pusat perbelanjaan, hingga food court. Rencana tersebut sekaligus memperluas portofolio BIKE ke sektor properti, infrastruktur, dan pengembangan kawasan. Dari sisi skala, nilai investasi sekitar Rp1 triliun tersebut setara dengan sekitar 19 kali ekuitas perseroan pada semester I 2026 sebesar Rp51,40 miliar dan sekitar 10 kali total aset sebesar Rp96,05 miliar. Lalu, ada juga PT Ultrajaya Milk Industry & Trading Company Tbk (ULTJ) yang tengah berencana melakukan rights issue melalui penerbitan sebanyak-banyaknya 7,88 miliar saham baru. Jumlah tersebut setara dengan 43,11% dari modal ditempatkan dan disetor penuh setelah pelaksanaan PMHMETD IV. Harga pelaksanaan ditetapkan sebesar Rp2.150 per saham. Dengan demikian, perseroan berpotensi memperoleh dana hingga Rp16,94 triliun dari aksi korporasi tersebut. Sebanyak 86,01% dari dana yang dihimpun atau sekitar Rp14,57 triliun akan digunakan untuk mengambil alih 100% saham Frisian Flag Indonesia. Transaksi tersebut akan dilakukan melalui mekanisme inbreng atau penyetoran modal dalam bentuk selain uang. Sementara itu, bagian dana dalam bentuk setoran tunai akan digunakan untuk kebutuhan modal kerja, termasuk biaya bahan langsung, upah langsung, pemeliharaan, serta beban listrik. Nilai rencana transaksi inbreng tersebut mencapai 178,24% dari ekuitas perseroan. Karena nilainya memenuhi kriteria transaksi material, pelaksanaannya memerlukan persetujuan pemegang saham dalam RUPS. Setelah transaksi terlaksana, FrieslandCampina International Holding B.V. (FCIH) diproyeksikan menjadi pemegang saham pengendali baru ULTJ dengan kepemilikan sekitar 28,95% hingga 30,81%. FCIH juga wajib melakukan penawaran tender atas saham publik yang tersisa. Di sisi lain, pemegang saham lama yang tidak menggunakan haknya dalam PMHMETD IV berpotensi mengalami dilusi hingga maksimal 43,11%. Rencana aksi korporasi tersebut masih menunggu persetujuan RUPSLB yang dijadwalkan berlangsung pada 27 Oktober 2026. Rekomendasi Saham Hari Ini ANTM - Buy 3310-3330 | TP 3370-3420 | SL 3160 [Gambas:Produk Investasi by I', 'https://awsimages.detik.net.id/visual/2026/09/21/market-1789953458-1789953459361_169.jpeg?w=650&q=90', '2026-09-21 01:51:42.078+00', null, null, null, null, null, null, '2026-09-21 01:51:42.650561+00', '2026-09-21 01:51:42.650561+00', null, null, '2026-09-21 01:51:42.078+00', false, 'MACRO_ECONOMY', 'IHSG turun 0,33% di zona merah. Investor asing catat net sell Rp1,78 triliun. Rekomendasi saham hari ini termasuk ANTM, ARCI, dan VKTR.', 'CNBC Indonesia', 9, 'GENERATE', 'Berita mengandung aksi korporasi yang sangat signifikan (Rights Issue ULTJ senilai Rp16,94 triliun dan akuisisi Frisian Flag) serta proyek infrastruktur BIKE senilai Rp1 triliun, yang memiliki dampak langsung dan data kuantitatif yang sangat kuat.'), ('20eec132-a1e2-49d5-9ab4-688bf88534df', 'https://emitennews.com/news/sempat-php-klbf-gaspol-buyback-rp500-miliar', 'Kalbe Farma (KLBF) reinstates Rp500 billion share buyback after earlier cancellation', 'Kalbe Farma (KLBF) announced the reinstatement of its share buyback program valued at Rp500 billion after previously annulling the plan. The buyback will be executed over three months, from 17 September to 17 December 2026, using internal cash as the financing source. Management estimates the full buyback will lower interest income by about Rp8.4 billion, a non‑material impact, while projecting pro‑forma earnings per share of Rp81.44, up from Rp80.51 for the fiscal year ended 31 December 2025. The company said the program is intended to reinforce investor confidence and may provide flexibility for future treasury‑stock use.', 'https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789522407.jpeg?25119ab', '2026-09-16 08:34:00+00', 'healthcare', ARRAY['pharmaceuticals-health-care-research'], ARRAY['KLBF.JK'], ARRAY['Stock Buyback','Financial Metrics','Capital & Funding','Bullish'], '{"future":1,"dividend":0,"ownership":0,"technical":0,"valuation":1,"financials":0,"management":0,"sustainability":0}', '{"body":"Kalbe Farma (KLBF) announced the reinstatement of its share buyback program valued at Rp500 billion after previously annulling the plan. The buyback will be executed over three months, from 17 September to 17 December 2026, using internal cash as the financing source. Management estimates the full buyback will lower interest income by about Rp8.4 billion, a non‑material impact, while projecting pro‑forma earnings per share of Rp81.44, up from Rp80.51 for the fiscal year ended 31 December 2025. The company said the program is intended to reinforce investor confidence and may provide flexibility for future treasury‑stock use.","tags":["Stock Buyback","Financial Metrics","Capital & Funding","Bullish"],"title":"Kalbe Farma (KLBF) reinstates Rp500 billion share buyback after earlier cancellation","sector":"healthcare","source":"https://emitennews.com/news/sempat-php-klbf-gaspol-buyback-rp500-miliar","symbols":["KLBF.JK"],"dimension":{"future":1,"dividend":0,"ownership":0,"technical":0,"valuation":1,"financials":0,"management":0,"sustainability":0},"thumbnail":"https://ap-south-1.linodeobjects.com/emitennews-02/uploads/news/thumb_1789522407.jpeg?25119ab","timestamp":"2026-09-16T08:34:00","sub_sector":["pharmaceuticals-health-care-research"]}', '2026-09-17 06:49:25.547472+00', '2026-09-17 06:49:25.547472+00', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 5, '2026-09-16 08:34:00+00', false, null, null, null, 0, 'PASS', null), ('212f7299-17d8-494e-8142-cdb0339048a8', 'https://www.idxchannel.com/market-news/pengendali-baru-masuk-dpum-siapkan-ekspansi-rp100-miliar', 'Pengendali Baru Masuk, DPUM Siapkan Ekspansi Rp100 Miliar', 'Advertisement IDX Channel Market news Pengendali Baru Masuk, DPUM Siapkan Ekspansi Rp100 Miliar Market news Desi Angriani 19/09/2026 13:05 WIB Ekspansi tersebut mendapat dukungan dari pengendali baru perseroan, PT Rama Indonesia yang merupakan bagian dari Unirama Group Pengendali Baru Masuk, DPUM Siapkan Ekspansi Rp100 Miliar (Foto: dok DPUM) A A A IDXChannel – PT Dua Putra Utama Makmur Tbk (DPUM) menyiapkan belanja modal (capital expenditure/capex) sekitar Rp100 miliar untuk mendukung ekspansi usaha pada 2026. Rencana tersebut mendapat dukungan dari pengendali baru perseroan, PT Rama Indonesia yang merupakan bagian dari Unirama Group yang bergerak di bidang solusi rantai pasok dan distribusi barang konsumsi atau fast-moving consumer goods (FMCG). Baca Juga: 20 Saham Top Loser Sepanjang Juni 2026, DPUM hingga CDIA, Simak Daftar Emitennya Unirama Group memiliki jaringan distribusi dan infrastruktur pergudangan di berbagai wilayah Pulau Jawa. Masuknya PT Rama Indonesia sebagai pengendali baru turut membuka arah pengembangan usaha DPUM. Namun, manajemen DPUM menegaskan realisasi rencana ekspansi tetap akan mempertimbangkan sejumlah faktor, termasuk hasil evaluasi, ketersediaan pendanaan serta kondisi usaha pada saat pelaksanaan. Baca Juga: Dua Putra Utama Makmur Tetapkan Nilai Wajar Saham DPUM Rp212 "Pelaksanaan rencana tersebut akan tunduk pada evaluasi, ketersediaan pendanaan, persetujuan organ Perseroan dan/atau regulator apabila dipersyaratkan, serta kondisi usaha pada saat pelaksanaan," tutur manajemen dalam keterbukaan informasi BEI, Selasa (15/9/2026). Halaman :